SELECT 'loucka_reconstruction' source_database,t.target_time,t.gap_id,t.gap_seconds,t.protection_scope,a.usUnits source_usUnits,a.interval source_interval,a.`outTemp` AS `outTemp`, a.`outHumidity` AS `outHumidity`, a.`rain` AS `rain`, a.`rainRate` AS `rainRate`, a.`barometer` AS `barometer`, a.`pressure` AS `pressure`, a.`altimeter` AS `altimeter`, a.`inTemp` AS `inTemp`, a.`inHumidity` AS `inHumidity`, a.`windSpeed` AS `windSpeed`, a.`windDir` AS `windDir`, a.`windGust` AS `windGust`, a.`windGustDir` AS `windGustDir`, a.`dewpoint` AS `dewpoint`, a.`windchill` AS `windchill`, a.`heatindex` AS `heatindex`, a.`ET` AS `ET`, a.`radiation` AS `radiation`, a.`UV` AS `UV`, a.`extraTemp1` AS `extraTemp1`, a.`extraTemp2` AS `extraTemp2`, a.`soilTemp1` AS `soilTemp1`, a.`soilTemp2` AS `soilTemp2`, a.`soilTemp3` AS `soilTemp3`, a.`soilTemp4` AS `soilTemp4`, a.`soilMoist1` AS `soilMoist1`,p.dateTime source_prev_time,p.outTemp source_prev_outTemp,n.dateTime source_next_time,n.outTemp source_next_outTemp,l.outTemp left_outTemp,r.outTemp right_outTemp,l.outHumidity left_outHumidity,r.outHumidity right_outHumidity,l.rain left_rain,r.rain right_rain,(SELECT COUNT(*) FROM loucka_reconstruction.reconstruction_changes c WHERE c.target_time=t.target_time) change_event_count,(SELECT COUNT(*) FROM loucka_reconstruction.reconstruction_changes c WHERE c.target_time=t.target_time AND c.variable='outTemp') outTemp_change_event_count,(SELECT COUNT(*) FROM loucka_reconstruction.reconstruction_changes c WHERE c.target_time=t.target_time AND c.variable='outHumidity') outHumidity_change_event_count,(SELECT COUNT(*) FROM loucka_reconstruction.reconstruction_changes c WHERE c.target_time=t.target_time AND c.variable='rain') rain_change_event_count FROM targets t JOIN `loucka_reconstruction`.archive a ON a.dateTime=t.target_time LEFT JOIN `loucka_reconstruction`.archive p ON p.dateTime=t.target_time-300 LEFT JOIN `loucka_reconstruction`.archive n ON n.dateTime=t.target_time+300 LEFT JOIN loucka_reconstruction.archive l ON l.dateTime=t.left_time LEFT JOIN loucka_reconstruction.archive r ON r.dateTime=t.right_time LEFT JOIN loucka_reconstruction.archive current_row ON current_row.dateTime=t.target_time WHERE current_row.dateTime IS NULL
UNION ALL
